"""Small daily check-in over a real private diary; no fake bank feeds or scores."""
DIARY_CSS = r'''
.money-buddy-card{padding:24px;border:1px solid var(--line);border-radius:24px;background:linear-gradient(120deg,var(--panel),var(--panel2));margin:20px 0}.money-buddy-card h2{margin:0;font-size:24px;letter-spacing:-.035em}.money-buddy-card p{color:var(--muted);line-height:1.6;font-size:13px}.diary-top{display:flex;align-items:center;justify-content:space-between;gap:14px}.diary-top .everyday-icon-tile{background:#e9e6fb}.diary-figures{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:18px 0}.diary-figure{padding:15px;border-radius:16px;background:var(--panel);border:1px solid var(--line)}.diary-figure small{display:block;color:var(--muted);font-size:11px}.diary-figure strong{display:block;font-size:22px;letter-spacing:-.04em;margin-top:8px;overflow-wrap:anywhere}.diary-meter{width:100%;height:12px;border:0;border-radius:20px;overflow:hidden;background:#e7e5f2}.diary-meter::-webkit-progress-bar{background:#e7e5f2;border-radius:20px}.diary-meter::-webkit-progress-value{background:linear-gradient(90deg,#aaa3ec,#82b8ad);border-radius:20px;transition:width .4s ease}.diary-meter::-moz-progress-bar{background:#8b86c8}.diary-status{padding:12px 14px;border-radius:14px;background:var(--panel2);border:1px solid var(--line)}.diary-status[data-tone=warning]{border-color:#bf8e56}.diary-status[data-tone=shortfall]{border-color:#c9797b}.diary-fields{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0}.diary-fields label{display:grid;gap:6px;flex:1;min-width:120px;font-size:12px}.money-buddy-card input,.money-buddy-card select,.money-buddy-card textarea{font:inherit;color:var(--ink);background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:11px;min-height:44px;width:100%;box-sizing:border-box}.money-buddy-card textarea{resize:vertical;min-height:74px}.diary-actions{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.money-buddy-card button{font:600 12px inherit;min-height:44px;border:1px solid var(--line);border-radius:13px;padding:10px 14px;background:var(--panel);color:var(--ink);cursor:pointer}.money-buddy-card button.primary{background:#d5d0f2;color:#242239;border-color:#b5aedb}.diary-proposal{border:1px solid #a9a1d0;border-radius:16px;padding:16px;margin-top:14px}.diary-row{display:flex;justify-content:space-between;gap:12px;align-items:center;border-bottom:1px solid var(--line);padding:12px 0;font-size:13px}.diary-row small{display:block;color:var(--muted);margin-top:5px}.diary-checkin{margin-top:18px;border-top:1px solid var(--line);padding-top:18px}.diary-milestone{display:inline-block;padding:6px 10px;border-radius:20px;background:var(--panel2);font-size:11px;border:1px solid var(--line)}.buddy-core .diary-companion{width:88px;height:88px;object-fit:contain;animation:friday-float 6s ease-in-out infinite}.buddy-core:before,.buddy-core:after{display:none}.friday-buddy[data-state=working] .diary-companion{animation:friday-thinking 1.8s ease-in-out infinite}.friday-buddy[data-state=error] .diary-companion{animation:none;filter:saturate(.6)}.friday-typed{display:block;min-height:1.5em;font-size:14px;font-weight:600;color:var(--ink);margin:8px 0}.friday-typed:after{content:'';display:inline-block;height:1em;border-right:2px solid #8b83b8;margin-left:3px;vertical-align:middle}.friday-typed[data-settled=true]:after{display:none}@keyframes friday-float{50%{transform:translateY(-5px) rotate(2deg)}}@keyframes friday-thinking{50%{transform:scale(1.04) translateY(-2px)}}@media(max-width:650px){.money-buddy-card{padding:18px}.diary-figures{grid-template-columns:1fr}.diary-figure strong{font-size:24px}.diary-row{align-items:flex-start}}@media(prefers-reduced-motion:reduce){.buddy-core .diary-companion{animation:none}.diary-meter::-webkit-progress-value{transition:none}}html[data-motion=off] .buddy-core .diary-companion{animation:none}html[data-motion=off] .diary-meter::-webkit-progress-value{transition:none}
'''

DIARY_JS = r'''
    {
      const card=element('section',null,'money-buddy-card');card.id='friday-money-diary';card.setAttribute('aria-label','My money today');
      const top=element('div',null,'diary-top');top.append(element('h2','My money today'),everydayTile('heart','lavender'));card.append(top,element('p','A quick check-in. A clearer picture. Your reports only—not a bank connection.'));
      const summary=element('div'),setup=element('form'),checkin=element('div',null,'diary-checkin'),proposal=element('div'),history=element('details');history.append(element('summary','My recent updates'));const rows=element('div');history.append(rows);
      const feedback=element('p','Loading your private diary…','diary-status');feedback.setAttribute('role','status');
      const reload=element('button','Reload my diary');reload.type='button';
      let snapshot=null,busy=false,generation=0,pendingWrite=null;
      const amount=value=>{if(!/^\d+(?:\.\d{1,2})?$/.test(value.trim()))throw new Error('Enter rupees with at most two decimal places.');const [whole,fraction='']=value.trim().split('.');const n=Number(whole)*100+Number(fraction.padEnd(2,'0'));if(!Number.isSafeInteger(n)||n>10000000000)throw new Error('Amount is outside the diary limit.');return n;};
      const money=n=>'₹'+(n/100).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
      const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
      const label=(text,input)=>{const l=element('label',text);l.append(input);return l;};
      const opening=element('input'),buffer=element('input');[opening,buffer].forEach(x=>{x.type='text';x.inputMode='decimal';x.required=true;});opening.placeholder='For example, 8000';buffer.placeholder='For example, 2000';
      const fields=element('div',null,'diary-fields');fields.append(label('Cash before the updates you will log (₹)',opening),label('Buffer you want to keep (₹)',buffer));const start=element('button','Start my private diary','primary');start.type='submit';setup.append(fields,element('p','Store these amounts and confirmed entries in your private Friday workspace. No bank access or model call. Do not re-log expenses already included in opening cash.'),start);
      const text=element('textarea');text.maxLength=600;text.placeholder='Spent ₹250 on groceries. Received ₹1,000 today.';text.setAttribute('aria-label','Daily money update');
      const parse=element('button','Let Friday read this','primary');parse.type='button';const manual=element('details');manual.append(element('summary','Or add an entry without AI'));
      const manualForm=element('form'),manualFields=element('div',null,'diary-fields'),direction=element('select');[['OUT','Money out'],['IN','Money in']].forEach(([v,t])=>{const o=element('option',t);o.value=v;direction.append(o);});
      const value=element('input'),description=element('input'),when=element('input');value.inputMode='decimal';value.required=true;description.maxLength=80;description.required=true;when.type='date';when.required=true;when.value=today();when.max=today();manualFields.append(label('Direction',direction),label('Amount (₹)',value),label('Short note',description),label('Date',when));const preview=element('button','Review this entry');preview.type='submit';manualForm.append(manualFields,preview);manual.append(manualForm);
      checkin.append(element('h3','What changed today?'),text,element('p','“Let Friday read this” sends only this text to Gemini. Review before saving. Never enter PINs, OTPs or passwords. Expected future income belongs in the runway plan.'),parse,manual,proposal);
      const actions=element('div',null,'diary-actions');const coach=element('button','Ask Friday for one next step');coach.type='button';const runway=element('button','Plan what comes next');runway.type='button';actions.append(coach,runway,reload);card.append(summary,setup,checkin,feedback,actions,history);
      everydayMain.insertBefore(card,hero);
      const companion=document.querySelector('.buddy-core');if(companion){companion.replaceChildren(everydayImage('friday-orb','diary-companion'));}
      const typed=element('span',null,'friday-typed');typed.setAttribute('aria-hidden','true');typed.textContent='Hi, I’m Friday. Your money buddy.';typed.dataset.settled='true';document.querySelector('.friday-buddy h2')?.after(typed);
      let typingTimer=null;const typingMedia=matchMedia('(prefers-reduced-motion: reduce)');const settle=()=>{clearTimeout(typingTimer);typed.textContent='Hi, I’m Friday. Your money buddy.';typed.dataset.settled='true';};
      function intro(){settle();if(typingMedia.matches||document.documentElement.dataset.motion==='off'||document.hidden)return;const phrases=['Hi, I’m Friday. Your money buddy.','One small check-in. A little more clarity.'];let phrase=0,index=0;typed.dataset.settled='false';function tick(){if(document.hidden||typingMedia.matches||document.documentElement.dataset.motion==='off'){settle();return;}typed.textContent=phrases[phrase].slice(0,index++);if(index<=phrases[phrase].length){typingTimer=setTimeout(tick,45);return;}if(phrase===0){phrase=1;index=0;typingTimer=setTimeout(tick,1400);}else typingTimer=setTimeout(settle,1600);}tick();}
      typingMedia.addEventListener('change',settle);document.addEventListener('visibilitychange',()=>{if(document.hidden)settle();});new MutationObserver(()=>{if(document.documentElement.dataset.motion==='off')settle();}).observe(document.documentElement,{attributes:true,attributeFilter:['data-motion']});intro();
      function render(data){if(data.scope!=='USER_REPORTED_MONEY_DIARY'||data.money_moved!==false||data.bank_connected!==false||data.ai_called!==false)throw new Error('Unexpected diary authority');snapshot=data;summary.replaceChildren();rows.replaceChildren();setup.hidden=!!data.summary;checkin.hidden=!data.summary;coach.disabled=!data.summary;runway.disabled=!data.summary;history.hidden=!data.summary;when.max=today();
        if(!data.summary){feedback.textContent='Start with your cash before new entries and a buffer target. Nothing has been assumed.';return;}
        const s=data.summary,grid=element('div',null,'diary-figures');[['Reported cash',s.reported_cash_minor],['Logged money in',s.money_in_minor],['Logged money out',s.money_out_minor]].forEach(([title,n])=>{const box=element('div',null,'diary-figure');box.append(element('small',title),element('strong',money(n)));grid.append(box);});summary.append(grid);
        const meter=element('progress',null,'diary-meter');meter.max=100;meter.value=s.buffer_coverage_percent;meter.setAttribute('aria-label','Coverage of your chosen cash buffer');const note=element('p',null,'diary-status');note.dataset.tone=s.status==='REPORTED_SHORTFALL'?'shortfall':s.status==='BUFFER_BELOW_TARGET'?'warning':'neutral';note.textContent=s.status==='REPORTED_SHORTFALL'?'Your reported cash is below zero. Check missing entries and upcoming essentials.':s.status==='BUFFER_BELOW_TARGET'?'Your chosen buffer is '+money(s.buffer_gap_minor)+' short in these reports. Let’s review the next expense.':'Your chosen buffer is covered in these reports. Upcoming bills can still change the picture.';summary.append(element('p',s.buffer_coverage_percent+'% of your '+money(s.buffer_minor)+' buffer target · not a credit score'),meter,note,element('p',s.active_entries+' active entries · updated '+data.updated_at.slice(0,10)),element('span',s.check_in_days?'You checked in on '+s.check_in_days+' day(s). Small steps count.':'Ready for your first check-in.','diary-milestone'));
        data.entries.slice().reverse().slice(0,12).forEach(e=>{const row=element('div',null,'diary-row');const info=element('div');info.append(element('b',e.label),element('small',e.date+' · '+(e.undone?'Undone':e.direction==='IN'?'Money in':'Money out')));row.append(info,element('b',money(e.amount_minor)));if(!e.undone){const undo=element('button','Undo');undo.type='button';undo.addEventListener('click',()=>{proposal.replaceChildren();const box=element('section',null,'diary-proposal');const confirmUndo=element('button','Confirm diary undo','primary');confirmUndo.type='button';confirmUndo.addEventListener('click',()=>write({action:'UNDO',undo_operation_id:e.operation_id}));const cancel=element('button','Keep my entry');cancel.type='button';cancel.addEventListener('click',()=>proposal.replaceChildren());box.append(element('h3','Undo this check-in group?'),element('p','All entries saved together in this check-in will be marked undone. This does not reverse any bank payment.'),confirmUndo,cancel);proposal.append(box);box.scrollIntoView({block:'nearest'});confirmUndo.focus();});row.append(undo);}rows.append(row);});
        const details=element('details');details.append(element('summary','What this meter means'));data.limits.forEach(t=>details.append(element('p',t)));rows.append(details);feedback.textContent='Saved reports loaded. No bank or payment action.';
      }
      async function operation(fn){if(busy)return;busy=true;card.setAttribute('aria-busy','true');card.querySelectorAll('button,input,select,textarea').forEach(e=>e.disabled=true);const current=generation;try{await fn(current);}catch(error){feedback.textContent=error.message+' Nothing is assumed paid. Reload to check whether a save completed.';}finally{busy=false;card.setAttribute('aria-busy','false');card.querySelectorAll('button,input,select,textarea').forEach(e=>e.disabled=false);coach.disabled=!snapshot?.summary;runway.disabled=!snapshot?.summary;}}
      async function read(current){const data=await jsonRequest('/api/friday/diary');if(current!==generation)return;render(data);}
      function write(change){
        if(!snapshot){feedback.textContent='Reload your diary first. No cash is assumed.';return;}
        if(pendingWrite){feedback.textContent='A previous save is unconfirmed. Reload and resolve that same update before adding another.';return;}
        operation(async current=>{const body={operation_id:crypto.randomUUID().replaceAll('-',''),expected_revision:snapshot.revision,workspace_generation:snapshot.workspace_generation,confirm_store:true,...change};pendingWrite=body;feedback.textContent='Saving your confirmed diary update. No money moves.';const data=await jsonRequest('/api/friday/diary','POST',body);if(current!==generation)return;render(data);pendingWrite=null;proposal.replaceChildren();text.value='';document.dispatchEvent(new CustomEvent('friday:diary-updated'));});
      }
      setup.addEventListener('submit',event=>{event.preventDefault();try{write({action:'START',opening_cash_minor:amount(opening.value),buffer_minor:amount(buffer.value)});}catch(e){feedback.textContent=e.message;}});
      function showProposal(entries,source){proposal.replaceChildren();if(!entries.length)return;const box=element('section',null,'diary-proposal');box.append(element('h3','Does this look right?'),element('p',source+' · not saved yet. Undo remains available after saving.'));
        entries.forEach(e=>{const row=element('p',(e.direction==='IN'?'Money in: ':'Money out: ')+money(e.amount_minor)+' · '+e.label+' · '+e.date);box.append(row);if(e.source_quote)box.append(element('p','“'+e.source_quote+'”'));});const save=element('button','Confirm & save privately','primary');save.type='button';save.addEventListener('click',()=>write({action:'ADD',entries:entries.map(({source_quote,...e})=>e)}));const cancel=element('button','Discard');cancel.type='button';cancel.addEventListener('click',()=>proposal.replaceChildren());box.append(save,cancel);proposal.append(box);}
      parse.addEventListener('click',()=>operation(async current=>{const raw=text.value.trim();if(raw.length<3)throw new Error('Write an update first, or use manual entry.');feedback.textContent='Friday is reading only this check-in. Nothing is saved yet.';proposal.replaceChildren();const result=await jsonRequest('/api/friday/diary/prepare','POST',{text:raw,confirm_cloud_processing:true});if(current!==generation)return;if(result.scope!=='UNSAVED_DIARY_PROPOSAL'||result.saved!==false||result.money_moved!==false)throw new Error('Unexpected proposal authority');if(!result.entries.length){feedback.textContent=result.clarification||'That update is unclear. Add the amount and direction manually.';return;}showProposal(result.entries.map(e=>({...e,date:today()})),'Gemini proposal; date set to today—use manual entry for another date');feedback.textContent=result.mode+' · '+result.model+' · one model call. Review direction, amount and note before saving.';}));
      text.addEventListener('input',()=>proposal.replaceChildren());manualForm.addEventListener('input',()=>proposal.replaceChildren());manualForm.addEventListener('submit',event=>{event.preventDefault();try{showProposal([{direction:direction.value,amount_minor:amount(value.value),label:description.value.trim(),date:when.value}],'Your manual entry; no model call');}catch(e){feedback.textContent=e.message;}});
      reload.addEventListener('click',()=>operation(async current=>{await read(current);proposal.replaceChildren();if(pendingWrite){const retry=element('button','Retry the same unconfirmed save');retry.type='button';retry.addEventListener('click',()=>operation(async c=>{const data=await jsonRequest('/api/friday/diary','POST',pendingWrite);if(c!==generation)return;render(data);pendingWrite=null;proposal.replaceChildren();document.dispatchEvent(new CustomEvent('friday:diary-updated'));}));proposal.append(element('p','A previous save was not confirmed by this page. Check your loaded entries first. Same-ID retry cannot add the group twice.'),retry);}}));
      coach.addEventListener('click',()=>{show('coach');const consent=$('friday-chat-diary');consent.closest('details').open=true;consent.focus();$('home-command').value='Explain my shared money diary summary and suggest one practical next step. Do not treat it as a bank balance, earnings, a credit score or guaranteed future safety.';$('home-command').focus();toast('Choose diary-summary sharing, then Ask Friday. Only totals are shared.');});
      runway.addEventListener('click',()=>{show('money');const cash=document.querySelector('#friday-runway input[aria-label="Available cash (INR)"]');if(snapshot.summary.reported_cash_minor<0){toast('Your reports are below zero. Review them before starting a non-negative cash scenario.');return;}if(cash){cash.value=String(snapshot.summary.reported_cash_minor/100);cash.dispatchEvent(new Event('input',{bubbles:true}));cash.focus();toast('Reported cash copied into the plan, not saved or calculated. Review dates and future bills; do not log the same expense twice.');}});
      const download=element('button','Download my diary');download.type='button';download.addEventListener('click',()=>{if(!snapshot?.summary){toast('Start your diary before exporting it.');return;}const url=URL.createObjectURL(new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'}));const link=element('a');link.href=url;link.download='friday-user-reported-diary.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});actions.append(download);
      const diaryConsent=element('input');diaryConsent.type='checkbox';diaryConsent.id='friday-chat-diary';const consentLabel=element('label',' Include my money diary totals (no entry notes) in Gemini’s reply','friday-chat-consent');consentLabel.prepend(diaryConsent);const commandForm=document.querySelector('#home-command').closest('form');commandForm.before(consentLabel);diaryConsent.addEventListener('change',()=>document.dispatchEvent(new CustomEvent('friday:diary-updated')));
      const startToday=element('button','Log a money update');startToday.type='button';startToday.addEventListener('click',()=>{show('tools');card.scrollIntoView({block:'start'});(snapshot?.summary?text:opening).focus();});document.querySelector('.buddy-actions')?.prepend(startToday);
      document.addEventListener('friday:cashflow-cleared',()=>{generation++;snapshot=null;pendingWrite=null;proposal.replaceChildren();summary.replaceChildren();rows.replaceChildren();text.value='';diaryConsent.checked=false;setup.hidden=false;checkin.hidden=true;feedback.textContent='Diary cleared with private-input cleanup. Reload before starting again.';});
      const before=show;show=function(name,push=true){before(name,push);if(name==='home'&&!busy)operation(read);};operation(read);
    }
'''
